/** Runtime Supplies economy, building income calculation, post-run scoring,
 * Sparks of Defiance tier calculation, and Void Essence anti-instant-abort gate. */

import { SCORING_RULES, SUPPLIES_ECONOMY } from "./config.ts";
import {
  CellMaterial,
  type PlayStyleMode,
  type RunOutcome,
  type ScenarioConfig,
  type ZeroContactReason,
} from "./model.ts";
import { recordScenarioResult, type EvaluatedTech, type SparksTier, type VoidTechWallet } from "./tech/wallet.ts";
import type { VoidWorld } from "./world.ts";

/** Computes the periodic Supplies generated by all surviving & developed civilian buildings.
 * Taller buildings earn more: 1 surviving floor = $1 per 5 seconds ($0.40 per 2s income cycle). */
export function computeCityIncomePerCycle(world: VoidWorld, tech: EvaluatedTech): number {
  let total = SUPPLIES_ECONOMY.passiveTricklePerSec * 2;
  const { columnFloors, buildingAt, material, hp } = world;
  for (const b of world.buildings) {
    if (b.cells.length === 0) continue;
    let remainingFloors = 0;
    for (let i = 0; i < b.cells.length; i++) {
      const cIdx = b.cells[i];
      if (buildingAt[cIdx] === b.id && material[cIdx] !== CellMaterial.VOID && hp[cIdx] > 0) {
        remainingFloors += columnFloors ? columnFloors[cIdx] : b.height;
      }
    }
    if (remainingFloors <= 0) continue;
    const avgFloors = remainingFloors / b.cells.length;
    total += avgFloors * (2 / 5) * b.development * tech.cityIncomeMultiplier;
  }
  return Math.max(2, Math.round(total));
}

/** Evaluates Sparks of Defiance tier (0..3) from preserved baseline ratio [0..1]. */
export function computeSparksTier(won: boolean, preservedRatio: number, isEndless = false): SparksTier {
  if (!won || isEndless) return 0;
  const [t1, t2, t3] = SCORING_RULES.sparksThresholds;
  if (preservedRatio >= t3) return 3;
  if (preservedRatio >= t2) return 2;
  if (preservedRatio >= t1) return 1;
  return 0;
}

/** Evaluates post-run rewards, enforcing the anti-instant-abort participation check:
 * Starting a battle and immediately surrendering or doing nothing yields 0 Void Essence.
 * Meaningful participation requires either:
 * - Winning the scenario, OR
 * - Placing at least 1 structure/strike AND surviving at least `minParticipationSeconds`
 *   (or resisting at least `minWorkResisted` Void work). */
export function evaluateRunOutcome(
  scenario: ScenarioConfig,
  mode: PlayStyleMode,
  status: "won" | "lost",
  reason: ZeroContactReason,
  elapsedSeconds: number,
  world: VoidWorld,
  workResisted: number,
  playerActionsCount: number,
  wallet: VoidTechWallet,
): RunOutcome {
  const { preservedRatio, preservedPercent } = world.computePreservedBaseline();
  const sparksTier = computeSparksTier(status === "won", preservedRatio, scenario.endless);

  const participated =
    status === "won" ||
    (playerActionsCount > 0 &&
      (elapsedSeconds >= SCORING_RULES.minParticipationSeconds ||
        workResisted >= SCORING_RULES.minWorkResisted));

  let rawEssence = 0;
  if (status === "won") {
    rawEssence =
      SCORING_RULES.victoryBonusEssence +
      workResisted * SCORING_RULES.essencePerWorkResisted +
      preservedPercent * SCORING_RULES.essencePerPreservedPercentOnWin;
  } else if (participated) {
    const fullVictoryBenchmark =
      SCORING_RULES.victoryBonusEssence +
      (Number.isFinite(scenario.initialVoidEnergy) ? scenario.initialVoidEnergy : 4500) *
        SCORING_RULES.essencePerWorkResisted;
    rawEssence = Math.min(
      fullVictoryBenchmark * SCORING_RULES.maxLossEssenceShare,
      Math.max(4, workResisted * SCORING_RULES.essencePerWorkResisted + elapsedSeconds * 0.18),
    );
  }

  const { sparksDelta, essenceAdded } = recordScenarioResult(
    wallet,
    scenario.id,
    mode,
    status === "won",
    preservedPercent,
    sparksTier,
    rawEssence,
  );

  if (scenario.endless && elapsedSeconds > wallet.endlessBestSeconds) {
    wallet.endlessBestSeconds = Math.round(elapsedSeconds * 10) / 10;
  }

  return {
    scenarioId: scenario.id,
    mode,
    status,
    reason,
    elapsedSeconds: Math.round(elapsedSeconds * 10) / 10,
    preservedRatio,
    preservedPercent,
    sparksTier,
    sparksAwarded: sparksDelta,
    voidEssenceAwarded: essenceAdded,
    workResisted: Math.round(workResisted),
    participated,
  };
}
